window.RTLBenchLSData.register("assets/d35cf5d85aecb83be0d87f4951b62b47ac405a6f0eabe4c85f583f14d91f0c48.txt","module autovcoder_083487 #(\n    parameter number_bits = 22,  // 1 bit sign +9 int ( 3 ovr + 7 data)+ 11 fraction\n    parameter weight_bits = 12   // [1 bit sign + 11 data] (fraction)\n) (\n\n    input  wire [number_bits-1:0] num,     // 21-bit  input  data\n    input  wire [weight_bits-1:0] weight,  // 8-bit   input  data weight +1 bit sign\n    output reg  [number_bits-1:0] out      // 21-bit output data\n);\n\n  wire flag;  // determine the sign of the product\n  wire [number_bits+weight_bits-1-1:0] mul;\n  wire [number_bits-1-1:0] cut_data;  //20 bits for data without sign\n  reg  [number_bits+weight_bits-1-1:0] result_of_product; // 20bits *11 bits  =30data +1 ovr = 31 bits >>>> product without sign\n\n  //**************************** multiplication (weight and num without sign) ****************************\n  always @(*) begin\n    case (weight[weight_bits-1-1:0])\n      11'b00000000000: result_of_product = 31'b0;\n      11'b11111011000:\n      result_of_product = ( num[number_bits-2:0] << 3 ) +( num[number_bits-2:0] << 4 )+( num[number_bits-2:0] << 6 )+( num[number_bits-2:0] << 7 )+ ( num[number_bits-2:0] << 8 ) + ( num[number_bits-2:0] << 9 ) + ( num[number_bits-2:0] << 10 ); //0.9807\n      11'b11101100100:\n      result_of_product = ( num[number_bits-2:0] << 2 ) + ( num[number_bits-2:0] <<5 ) + ( num[number_bits-2:0] << 6 ) + ( num[number_bits-2:0] << 8 )+( num[number_bits-2:0] << 9 )+ ( num[number_bits-2:0] << 10 ); //0.9238\n      11'b11010100111:\n      result_of_product = ( num[number_bits-2:0] << 0 ) + ( num[number_bits-2:0] << 1 ) + ( num[number_bits-2:0] << 2 )  + ( num[number_bits-2:0] << 5 ) + ( num[number_bits-2:0] << 7 )+ ( num[number_bits-2:0] << 9 )+ ( num[number_bits-2:0] << 10 ); //0.8314\n      11'b10110101000:\n      result_of_product = ( num[number_bits-2:0] << 3 ) + ( num[number_bits-2:0] << 5 ) + ( num[number_bits-2:0] << 7 )  + ( num[number_bits-2:0] << 8 ) + ( num[number_bits-2:0] << 10 );//0.7071  \n      11'b10001110010:\n      result_of_product = ( num[number_bits-2:0] << 1 ) + ( num[number_bits-2:0] << 4 )+( num[number_bits-2:0] << 5 )+( num[number_bits-2:0] << 6 )+ ( num[number_bits-2:0] << 10 );//0.5555\n      11'b01100010000:\n      result_of_product = ( num[number_bits-2:0] << 4 ) + ( num[number_bits-2:0] << 8 )+( num[number_bits-2:0] << 9 );//0.3826\n      11'b00110001111:\n      result_of_product = ( num[number_bits-2:0] << 0 ) + ( num[number_bits-2:0] << 1 )+( num[number_bits-2:0] << 2 )+ ( num[number_bits-2:0] << 3 )+ ( num[number_bits-2:0] <<7 )+ ( num[number_bits-2:0] << 8 );//0.1950\n      11'b11111111111:\n      result_of_product = (num[number_bits-2:0] << 11);  // this will persent -1 and 1 as 1 11111111\n      default: result_of_product = 31'b0;\n    endcase\n  end\n  //**********************************************************************************************************************************\n  //******************************* Determine the sign of the product. **************************************************************\n  assign flag = num[number_bits-1] ^ weight[weight_bits-1];\n  //******************************* result of product is reg and. **************************************************************               \n  assign cut_data = result_of_product[30:weight_bits-1];  //[(number_bits-1) +(weight_bits-1)]- 1(sign) =30\n  //**********************************************************************************************************************************\n\n  //if weight is 0 and num is -ve i want out to be +0 not -0 \n  always @(*) begin\n    if (result_of_product == 0) out = 0;\n    else out = {flag, cut_data};\n  end\n\nendmodule\n\n");
